package edu.uao.yugioh.view; import edu.uao.yugioh.model.*; import javax.swing.*; import java.awt.*; import java.util.function.BiConsumer; public class BatallaView extends JFrame { private final JComboBox<Monstruo> cmbAtacante=new JComboBox<>(),cmbDefensor=new JComboBox<>(); private final JLabel lp1=new JLabel(),lp2=new JLabel(),estado=new JLabel("Seleccione cartas para iniciar el combate"); private BiConsumer<Monstruo,Monstruo> accion; public BatallaView(){initComponents();} private void initComponents(){setTitle("Fase de Batalla - Yu-Gi-Oh!");setDefaultCloseOperation(EXIT_ON_CLOSE);setSize(700,400);setLocationRelativeTo(null); JPanel p=new JPanel(new BorderLayout(12,12));p.setBorder(BorderFactory.createEmptyBorder(20,20,20,20));JPanel datos=new JPanel(new GridLayout(2,2,8,8));datos.add(lp1);datos.add(lp2);datos.add(new JLabel("Atacante:"));datos.add(cmbAtacante);p.add(datos,BorderLayout.NORTH);JPanel centro=new JPanel(new GridLayout(2,2,8,8));centro.add(new JLabel("Defensor (vacío = ataque directo):"));centro.add(cmbDefensor);JButton atacar=new JButton("ATACAR");atacar.addActionListener(e->{if(accion!=null)accion.accept((Monstruo)cmbAtacante.getSelectedItem(),(Monstruo)cmbDefensor.getSelectedItem());});centro.add(atacar);p.add(centro,BorderLayout.CENTER);p.add(estado,BorderLayout.SOUTH);add(p);} public void configurar(Jugador a,Jugador b,BiConsumer<Monstruo,Monstruo> accion){this.accion=accion;lp1.setText(a.getNombre()+" LP: "+a.getLp());lp2.setText(b.getNombre()+" LP: "+b.getLp());for(Monstruo m:a.getCampo())cmbAtacante.addItem(m);for(Monstruo m:b.getCampo())cmbDefensor.addItem(m);cmbDefensor.insertItemAt(null,0);cmbDefensor.setSelectedIndex(0);} public void mostrarResultado(ResultadoCombate r,Jugador a,Jugador b){lp1.setText(a.getNombre()+" LP: "+a.getLp());lp2.setText(b.getNombre()+" LP: "+b.getLp());estado.setText(r.toString());JOptionPane.showMessageDialog(this,r.toString(),"Resultado del combate",JOptionPane.INFORMATION_MESSAGE);} }